from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];data=json.loads((R/'manifest.json').read_text(encoding='utf8'));new=[c for c in data if c['source_video']=='V05'];count=len(data)
f=R/'tools/write_catalog.py';s=f.read_text(encoding='utf8').replace('四条参考视频','五条参考视频').replace('共 39 种可复用样式',f'共 {count} 种可复用样式').replace('当前 39 项',f'当前 {count} 项');s=s.replace("'V04':'视频 4｜考拉fufu 洗发水分享'","'V04':'视频 4｜考拉fufu 洗发水分享','V05':'视频 5｜考拉fufu 秋冬内搭穿搭'");f.write_text(s,encoding='utf8')
f=R/'tools/make_gallery.py';s=f.read_text(encoding='utf8').replace('四条参考视频','五条参考视频').replace('用户提供的四条视频','用户提供的五条视频').replace("'V03','V04','T'","'V03','V04','V05','T'");f.write_text(s,encoding='utf8')
lines=['# V05｜考拉fufu 秋冬内搭穿搭 · 包装拆解','','原片 145 秒（2分25秒），1080×1920，30fps。本次整理 R40–R54 共 15 项，其中 3 项明确保留为既有文字包装的变体。均处于待评审状态。','','| 编号 | 代表时间 | 包装 | 结构与动作 | 与旧库关系 |','|---|---|---|---|---|']
for c in new:
 t=c['source_time'];rel='、'.join(c['related']) or '新结构';rel=('变体：' if c.get('variant') else '相关：')+rel
 lines.append(f"| {c['id']} | {int(t)//60:02}:{t%60:04.1f} | {c['name']} | {c['observation']} | {rel} |")
lines+=['','## 去重与预设','','- 原片多次出现的白色常规字幕沿用 R31 的用途，不再重复新建。V05 中的字号、位置与粗细可作使用参数。','- 商品三色卡片只建 R40 一套，单张左上角商品挂图通过 images/positions 数量和坐标配置。','- Daily Photo 外框只建 R47，Look 01/02 的单品说明用 R49 叠加，不为每套服装重复建框。','- 黄色粗斜字、紫色卖点字和细金手写句分别作为 R50/R51/R52 变体，保留与 R32/R05 的关联。','- 普通口播缩放、换装硬切、近景手摸面料属于拍摄或剪辑素材，不当作独立动画包装。','','## 复刻说明','','每项提供 effect.html、case.json、reference.jpg/mp4、preview.mp4、poster.png、compare.jpg。文字、图槽、框架和装饰尽量分层，能改的内容集中在 TPL。','','- 原始字体未知，花体近似使用库内 Great Vibes，中文使用本机字体或回退字体。','- 窗口、提示框、纸纹、图钉、条码与箭头为独立绘制；装饰条码不编码商品信息。','- 预览照片是原片局部或相邻镜头，部分带原片自有字幕；这些是预览底片内容，不是新模板的文字层。复用时请换无字素材。','- 三色卡片预览底片下移以给商品区留空间；拍立得照片做了透视校正，局部相纸边缘可能仍在。','- R44 人物为静帧手工轮廓，发丝和衣边仍需精修；替换透明视频可保留真实口播动作。','- R54 用高斯模糊、缩放和水平移位近似原片方向拖影，不是逐像素光流复刻。','- 音效尚未试听；预览为静音，未虚构声效。','- R53 靠近原片末尾，参考片段长度短于 3 秒。']
(R/'sources/V05/包装拆解表.md').write_text('\n'.join(lines)+'\n',encoding='utf8');(R/'sources/V05/新增模板.json').write_text(json.dumps(new,ensure_ascii=False,indent=2),encoding='utf8')
# Parameterize the existing verification and contact-sheet tools for subsequent source batches.
f=R/'tools/verify_v04.cjs';s=f.read_text(encoding='utf8');s=s.replace("const R=path.resolve(__dirname,'..'),cfg=", "const source=process.argv[2]||'V04';const R=path.resolve(__dirname,'..'),cfg=").replace("c.source_video==='V04'","c.source_video===source").replace("name:'V04'","name:source").replace("!==9)","!==cases.length)").replace("'sources/V04/预览页截图.png'","'sources/'+source+'/预览页截图.png'").replace("'sources/V04/验收记录.json'","'sources/'+source+'/验收记录.json'").replace("console.log('39 gallery entries; 9 new previews decoded; render(t) deterministic; no page errors')","console.log(data.length+' gallery entries; '+cases.length+' previews decoded; render(t) deterministic; no page errors')")
(R/'tools/verify_source.cjs').write_text(s,encoding='utf8')
f=R/'tools/make_v04_overview.py';s=f.read_text(encoding='utf8').replace('import json,math,subprocess','import json,math,subprocess,sys\nSOURCE=sys.argv[1] if len(sys.argv)>1 else "V04"').replace("c['source_video']=='V04'","c['source_video']==SOURCE").replace("R/'sources/V04/新增包装总览.jpg'","R/'sources'/SOURCE/'新增包装总览.jpg'").replace("R/'sources/V04'","R/'sources'/SOURCE").replace("R/'sources/V04/montage.txt'","R/'sources'/SOURCE/'montage.txt'").replace("R/'sources/V04/新增包装预览合集.mp4'","R/'sources'/SOURCE/'新增包装预览合集.mp4'").replace("print('Made overview images and 27s labeled preview montage')","print('Made '+SOURCE+' overview images and labeled preview montage')")
(R/'tools/make_source_overview.py').write_text(s,encoding='utf8');print(f'Catalog extended to {count}; dedicated V05 breakdown ready')
